import"./chunk-VC46IEJQ.js";var e=(r,n,a,o,i,l,s,t,h)=>({name:{en:r,zh:n},desc:{en:a[0],zh:a[1]},tour:{en:o[0],zh:o[1]},source:{confidence:i,refs:l,book:{en:s[0],zh:s[1]},unknown:{en:t[0],zh:t[1]},interpretation:{en:h[0],zh:h[1]}}}),d={id:"port-of-ibben",intro:{en:"The Port of Ibben, on the cold island of Ib in the Shivering Sea, is home to squat, hairy sailors and whalers. The novels barely describe it, so this scene is a restrained impression of a northern whaling port.",zh:"\u4F0A\u73ED\u6E2F\u4F4D\u4E8E\u98A4\u6296\u6D77\u4E2D\u5BD2\u51B7\u7684\u4F0A\u5E03\u5C9B\uFF0C\u662F\u77EE\u58EE\u591A\u6BDB\u7684\u6C34\u624B\u4E0E\u6355\u9CB8\u4EBA\u7684\u5BB6\u56ED\u3002\u5C0F\u8BF4\u51E0\u4E4E\u6CA1\u6709\u63CF\u5199\u5B83\uFF0C\u6240\u4EE5\u672C\u573A\u666F\u53EA\u662F\u5BF9\u4E00\u5EA7\u5317\u65B9\u6355\u9CB8\u6E2F\u7684\u514B\u5236\u60F3\u8C61\u3002"},notes:{en:"From the novels: the Ibbenese are squat, hairy sailors whose tarred whaling ships appear in foreign ports. From the companion book: the port lies on the south coast of Ib, a grey city of steep hills, cobbled alleys, busy docks and shipyards, lit by whale-oil lamps, and grown rich on whale bone, blubber and oil. The wharves, sheds, bone arch, houses and layout shown here are all invented.",zh:"\u5C0F\u8BF4\u53EF\u636E\uFF1A\u4F0A\u73ED\u4EBA\u77EE\u58EE\u591A\u6BDB\uFF0C\u4EE5\u822A\u6D77\u4E3A\u4E1A\uFF0C\u4ED6\u4EEC\u6D82\u6EE1\u7126\u6CB9\u7684\u6355\u9CB8\u8239\u5E38\u89C1\u4E8E\u5F02\u56FD\u6E2F\u53E3\u3002\u8BBE\u5B9A\u96C6\u53EF\u636E\uFF1A\u4F0A\u73ED\u6E2F\u4F4D\u4E8E\u4F0A\u5E03\u5C9B\u5357\u5CB8\uFF0C\u662F\u4E00\u5EA7\u7070\u6697\u7684\u57CE\u5E02\uFF0C\u5C71\u5761\u9661\u5CED\uFF0C\u5375\u77F3\u5C0F\u5DF7\u7EB5\u6A2A\uFF0C\u7801\u5934\u4E0E\u8239\u575E\u7E41\u5FD9\uFF0C\u4EE5\u9CB8\u6CB9\u706F\u7167\u660E\uFF0C\u9760\u9CB8\u9AA8\u3001\u9CB8\u8102\u4E0E\u9CB8\u6CB9\u81F4\u5BCC\u3002\u753B\u9762\u4E2D\u7684\u7801\u5934\u3001\u5DE5\u68DA\u3001\u9CB8\u9AA8\u62F1\u95E8\u3001\u623F\u5C4B\u4E0E\u5E03\u5C40\u5747\u4E3A\u81EA\u62DF\u3002"},tour:["whaling-harbour","flensing-wharf","rendering-sheds","whale-bone-arch","harbour-town","breakwater"],sources:[{ref:"agot",checked:"memory",note:{en:"Daenerys sees hairy men from the Port of Ibben at Illyrio's house in Pentos; recalled, not re-read.",zh:"\u4E39\u59AE\u8389\u4E1D\u5728\u6F58\u6258\u65AF\u4F0A\u5229\u91CC\u6B27\u7684\u5B85\u90B8\u4E2D\u89C1\u5230\u6765\u81EA\u4F0A\u73ED\u6E2F\u7684\u591A\u6BDB\u7537\u5B50\uFF1B\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u539F\u6587\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Wiki and concordance search summaries: squat, hairy Ibbenese; tar-black whaling ships; the port on Ib's south coast with steep hills, cobbled alleys, docks, shipyards and whale-oil lamps (the last details from the companion book). Pages could not be fetched.",zh:"\u7ECF\u7EF4\u57FA\u4E0E\u8BCD\u6761\u7D22\u5F15\u7684\u641C\u7D22\u6458\u8981\u5370\u8BC1\uFF1A\u4F0A\u73ED\u4EBA\u77EE\u58EE\u591A\u6BDB\uFF1B\u6355\u9CB8\u8239\u8239\u8EAB\u6D82\u6EE1\u9ED1\u7126\u6CB9\uFF1B\u4F0A\u73ED\u6E2F\u4F4D\u4E8E\u4F0A\u5E03\u5C9B\u5357\u5CB8\uFF0C\u5C71\u5761\u9661\u5CED\uFF0C\u6709\u5375\u77F3\u5C0F\u5DF7\u3001\u7801\u5934\u3001\u8239\u575E\u4E0E\u9CB8\u6CB9\u706F\uFF08\u540E\u51E0\u9879\u51FA\u81EA\u8BBE\u5B9A\u96C6\uFF09\u3002\u9875\u9762\u672C\u8EAB\u65E0\u6CD5\u6253\u5F00\u3002"}},{ref:"twoiaf",checked:"not-accessed",note:{en:"The companion book was not opened; its details are known only through the wiki summaries above.",zh:"\u672A\u7FFB\u9605\u8BBE\u5B9A\u96C6\u539F\u4E66\uFF1B\u5176\u4E2D\u7EC6\u8282\u4EC5\u901A\u8FC7\u4E0A\u8FF0\u7EF4\u57FA\u6458\u8981\u5F97\u77E5\u3002"}}],landmarks:{"whaling-harbour":e("Whaling Harbour","\u6355\u9CB8\u6E2F",["A grey bay of timber wharves where fat-bellied whalers, hulls black with tar, tie up under cold fog.","\u51B7\u96FE\u7B3C\u7F69\u7684\u7070\u8272\u6D77\u6E7E\uFF0C\u6728\u7801\u5934\u8FB9\u6CCA\u7740\u8239\u8179\u5BBD\u5706\u3001\u8239\u8EAB\u6D82\u6EE1\u9ED1\u7126\u6CB9\u7684\u6355\u9CB8\u8239\u3002"],["Cold fog, grey water and the reek of the whale trade.","\u51B7\u96FE\u3001\u7070\u6C34\uFF0C\u8FD8\u6709\u6355\u9CB8\u4E1A\u7684\u8165\u6C14\u3002"],"medium",["agot","awoiaf"],["The Ibbenese sail tarred whaling ships; the port has busy docks and shipyards.","\u4F0A\u73ED\u4EBA\u9A7E\u9A76\u6D82\u7126\u6CB9\u7684\u6355\u9CB8\u8239\uFF1B\u6E2F\u53E3\u7801\u5934\u4E0E\u8239\u575E\u5341\u5206\u7E41\u5FD9\u3002"],["Harbour shape and size.","\u6E2F\u53E3\u5F62\u6001\u4E0E\u89C4\u6A21\u3002"],["A straight stone-footed quay with timber piers.","\u77F3\u57FA\u76F4\u7801\u5934\u914D\u6728\u6808\u6865\u3002"]),"flensing-wharf":e("Flensing Wharf","\u5256\u9CB8\u7801\u5934",["A broad timber deck where a catch is hauled out and cut up, with winches and tall posts.","\u5BBD\u9614\u7684\u6728\u5E73\u53F0\uFF0C\u6355\u83B7\u7684\u9CB8\u88AB\u62D6\u4E0A\u6765\u5256\u5272\uFF0C\u65C1\u6709\u7EDE\u76D8\u4E0E\u9AD8\u6869\u3002"],["Here the hunt ends and the butchery begins.","\u72E9\u730E\u5728\u6B64\u7ED3\u675F\uFF0C\u5256\u5272\u7531\u6B64\u5F00\u59CB\u3002"],"low",["awoiaf"],["Whale bone, blubber and oil are Ibben's chief trade; how the catch is processed is not described.","\u9CB8\u9AA8\u3001\u9CB8\u8102\u4E0E\u9CB8\u6CB9\u662F\u4F0A\u73ED\u7684\u4E3B\u8981\u5546\u54C1\uFF1B\u5982\u4F55\u5904\u7406\u6355\u83B7\u7269\u672A\u89C1\u63CF\u5199\u3002"],["Whether and where the Ibbenese flense their catch ashore.","\u4F0A\u73ED\u4EBA\u662F\u5426\u5728\u5CB8\u4E0A\u5256\u9CB8\uFF0C\u53C8\u5728\u4F55\u5904\u3002"],["A long deck with two winch posts and a stylised carcass.","\u5E26\u4E24\u6839\u7EDE\u76D8\u6869\u7684\u957F\u5E73\u53F0\u4E0E\u793A\u610F\u6027\u7684\u9CB8\u4F53\u3002"]),"rendering-sheds":e("Rendering Sheds","\u71AC\u6CB9\u68DA",["Stone sheds with tall chimneys where blubber is boiled down to oil.","\u5E26\u9AD8\u70DF\u56F1\u7684\u77F3\u68DA\uFF0C\u9CB8\u8102\u5728\u6B64\u71AC\u6210\u6CB9\u3002"],["Smoke from these chimneys marks the port from far out at sea.","\u8FD9\u4E9B\u70DF\u56F1\u5192\u51FA\u7684\u70DF\uFF0C\u8FDC\u5728\u6D77\u4E0A\u4FBF\u80FD\u671B\u89C1\u3002"],"low",["awoiaf"],["Whale oil lights the city and is a chief export; where it is made is not described.","\u9CB8\u6CB9\u65E2\u7167\u4EAE\u5168\u57CE\uFF0C\u4E5F\u662F\u4E3B\u8981\u51FA\u53E3\u8D27\uFF1B\u5728\u4F55\u5904\u71AC\u5236\u672A\u89C1\u63CF\u5199\u3002"],["Whether oil is made in the port itself.","\u9CB8\u6CB9\u662F\u5426\u5C31\u5728\u6E2F\u5185\u71AC\u5236\u3002"],["Three sheds with chimneys on the east side; invented.","\u4E1C\u4FA7\u4E09\u5EA7\u5E26\u70DF\u56F1\u7684\u77F3\u68DA\uFF1B\u4E3A\u81EA\u62DF\u3002"]),"whale-bone-arch":e("Whale-Bone Arch","\u9CB8\u9AA8\u62F1\u95E8",["A gateway of great ribs marking the way into town. Invented.","\u4EE5\u5DE8\u5927\u808B\u9AA8\u642D\u6210\u7684\u62F1\u95E8\uFF0C\u6807\u793A\u5165\u57CE\u4E4B\u8DEF\u3002\u7EAF\u5C5E\u865A\u6784\u3002"],["An arch of bones tells you what this town lives on.","\u4E00\u9053\u9AA8\u62F1\uFF0C\u9053\u51FA\u8FD9\u5EA7\u57CE\u9760\u4EC0\u4E48\u4E3A\u751F\u3002"],"low",["awoiaf"],["Not mentioned anywhere.","\u4EFB\u4F55\u8D44\u6599\u90FD\u672A\u63D0\u53CA\u3002"],["Whether any such arch exists.","\u662F\u5426\u6709\u8FD9\u6837\u7684\u62F1\u95E8\u3002"],["A decorative, interpretive landmark only.","\u4EC5\u4E3A\u88C5\u9970\u6027\u7684\u60F3\u8C61\u5730\u6807\u3002"]),"harbour-town":e("Harbour Town","\u6E2F\u9547",["Low timber houses with turf and thatch roofs on a steep, rocky slope.","\u9661\u5CED\u5CA9\u5761\u4E0A\uFF0C\u8986\u7740\u8349\u76AE\u4E0E\u8305\u8349\u7684\u4F4E\u77EE\u6728\u5C4B\u3002"],["Houses huddle low against the wind off the Shivering Sea.","\u623F\u5C4B\u4F4E\u4F0F\uFF0C\u62B5\u6321\u98A4\u6296\u6D77\u5439\u6765\u7684\u5BD2\u98CE\u3002"],"low",["awoiaf"],["A grey city of steep hills and cobbled alleys; its buildings are not described.","\u4E00\u5EA7\u7070\u6697\u7684\u57CE\u5E02\uFF0C\u5C71\u5761\u9661\u5CED\uFF0C\u5375\u77F3\u5C0F\u5DF7\u7EB5\u6A2A\uFF1B\u5EFA\u7B51\u672A\u89C1\u63CF\u5199\u3002"],["Building style and plan.","\u5EFA\u7B51\u98CE\u683C\u4E0E\u5E03\u5C40\u3002"],["Gabled houses and longhouses in dull browns; the turf roofs are invented.","\u5C71\u5899\u5C4B\u4E0E\u957F\u5C4B\uFF0C\u8272\u8C03\u9EEF\u6DE1\uFF1B\u8349\u76AE\u5C4B\u9876\u4E3A\u81EA\u62DF\u3002"]),breakwater:e("Breakwater","\u9632\u6CE2\u5824",["Two stone arms that shelter the harbour from heavy northern seas.","\u4E24\u9053\u77F3\u5824\uFF0C\u4E3A\u6E2F\u53E3\u6321\u4F4F\u5317\u65B9\u7684\u6C79\u6D8C\u6D77\u6D6A\u3002"],["Stone arms keep the northern sea out of the harbour.","\u77F3\u5824\u628A\u5317\u65B9\u7684\u6D77\u6D6A\u6321\u5728\u6E2F\u5916\u3002"],"low",["awoiaf"],["Not described.","\u672A\u89C1\u63CF\u5199\u3002"],["Whether the port has breakwaters.","\u6E2F\u53E3\u662F\u5426\u8BBE\u6709\u9632\u6CE2\u5824\u3002"],["Two angled stone moles; invented.","\u4E24\u9053\u659C\u5411\u77F3\u5824\uFF1B\u4E3A\u81EA\u62DF\u3002"])}};export{d as default};
